CREATE TABLE IF NOT EXISTS registration_policy(id INTEGER PRIMARY KEY CHECK(id=1),required INTEGER NOT NULL CHECK(required IN (0,1)));
CREATE TABLE IF NOT EXISTS authentication_policy(id INTEGER PRIMARY KEY CHECK(id=1),login_code INTEGER NOT NULL,login_captcha INTEGER NOT NULL,registration_code INTEGER NOT NULL,registration_captcha INTEGER NOT NULL,revision INTEGER NOT NULL);
INSERT OR IGNORE INTO authentication_policy VALUES(1,0,0,1,1,0);
CREATE TABLE IF NOT EXISTS email_codes(email_key TEXT PRIMARY KEY,nonce TEXT NOT NULL,digest TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL,captcha_verified INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS email_sends(id TEXT PRIMARY KEY,email_key TEXT NOT NULL,ip_key TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS email_sends_email ON email_sends(email_key,created);
CREATE INDEX IF NOT EXISTS email_sends_ip ON email_sends(ip_key,created);
CREATE INDEX IF NOT EXISTS email_sends_time ON email_sends(created);
CREATE TABLE IF NOT EXISTS contact_codes(channel TEXT NOT NULL,subject TEXT NOT NULL,nonce TEXT NOT NULL,digest TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL,captcha_verified INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(channel,subject));
CREATE TABLE IF NOT EXISTS contact_sends(id TEXT PRIMARY KEY,channel TEXT NOT NULL,address_key TEXT NOT NULL,ip_key TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS contact_sends_address ON contact_sends(channel,address_key,created);
CREATE INDEX IF NOT EXISTS contact_sends_ip ON contact_sends(channel,ip_key,created);
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY,digest TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created INTEGER NOT NULL,expires INTEGER NOT NULL,revoked INTEGER,used INTEGER,user_id TEXT UNIQUE REFERENCES users(id));
CREATE TABLE IF NOT EXISTS invitation_audit(id TEXT PRIMARY KEY,invitation_id TEXT NOT NULL REFERENCES invitations(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS connect_devices(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token TEXT UNIQUE NOT NULL,name TEXT NOT NULL,client TEXT NOT NULL,created TEXT NOT NULL,last_used INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS connect_devices_user ON connect_devices(user_id,revoked);
CREATE TABLE IF NOT EXISTS connect_codes(code TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),client TEXT NOT NULL,redirect_uri TEXT NOT NULL,challenge TEXT NOT NULL,device_name TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_points(user_id TEXT PRIMARY KEY REFERENCES users(id),balance INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_points_ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),delta INTEGER NOT NULL,kind TEXT NOT NULL,ref TEXT,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_signup_bonus(id INTEGER PRIMARY KEY CHECK(id=1),amount INTEGER NOT NULL CHECK(amount>=0));
INSERT OR IGNORE INTO ai_signup_bonus VALUES(1,0);
CREATE TABLE IF NOT EXISTS admin_audit(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),target TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
